Go

Creating publishers with different targets

    // publish to an exchange with a routing key
    publisher, err := connection.NewPublisher(context.Background(), &ExchangeAddress{
                Exchange: "foo",
                Key:      "bar",
            }, nil)

    // publish to an exchange without a routing key
