        Queue: "some-queue"},
        nil)

JavaScript

Publishing a message

    // publish to an exchange with a routing key
    const publisher = await connection.createPublisher({
      exchange: { name: "foo", routingKey: "bar" },
    });

    // publish to an exchange without a routing key
    const publisher = await connection.createPublisher({
      exchange: { name: "foo" },
