    <?php

    require_once __DIR__ . '/vendor/autoload.php';
    use PhpAmqpLib\Connection\AMQPStreamConnection;
    use PhpAmqpLib\Message\AMQPMessage;
    use PhpAmqpLib\Wire\AMQPTable;

    $connection = new AMQPStreamConnection('localhost', 5672, 'guest', 'guest');
    $channel = $connection->channel();

    $channel->queue_declare('rpc_queue', false, true, false, false, false, new AMQPTable(['x-queue-type' => 'quorum']));

    function fib(int $n)
    {
        if ($n === 0) {
            return 0;
        }
        if ($n === 1) {
            return 1;
        }

        return fib($n-1) + fib($n-2);
    }

    echo " [x] Awaiting RPC requests\n";
    $callback = function (AMQPMessage $req) {
        $n = intval($req->getBody());
        echo ' [.] fib(', $n, ")\n";

        $msg = new AMQPMessage(
            (string) fib($n),
            ['correlation_id' => $req->get('correlation_id')]
        );

        $req->getChannel()->basic_publish(
            $msg,
            '',
            $req->get('reply_to')
        );
        $req->ack();
    };

    $channel->basic_qos(0, 1, false);
    $channel->basic_consume('rpc_queue', '', false, false, false, false, $callback);

    try {
        $channel->consume();
    } catch (\Throwable $exception) {
        echo $exception->getMessage();
    }

    $channel->close();
    $connection->close();

The server code is rather straightforward:

• As usual we start by establishing the connection, channel and declaring the queue.

• We might want to run more than one server process. In order to spread the load equally over multiple servers we need to set the prefetch_count setting in $channel.basic_qos.

• We use basic_consume to access the queue. Then we enter the while loop in which we wait for request messages, do the work and send the response back.

The code for our RPC client rpc_client.php:

    <?php

    require_once __DIR__ . '/vendor/autoload.php';
    use PhpAmqpLib\Connection\AMQPStreamConnection;
    use PhpAmqpLib\Channel\AMQPChannel;
    use PhpAmqpLib\Message\AMQPMessage;

    class FibonacciRpcClient
    {
        private AMQPStreamConnection $connection;
        private AMQPChannel $channel;
        private $callback_queue;
        private $response;
        private $corr_id;

        public function __construct()
        {
            $this->connection = new AMQPStreamConnection(
                'localhost',
                5672,
                'guest',
                'guest'
            );
            $this->channel = $this->connection->channel();
            list($this->callback_queue, ,) = $this->channel->queue_declare(
                "",
                false,
                false,
                true,
                false
            );
            $this->channel->basic_consume(
                $this->callback_queue,
                '',
                false,
                true,
                false,
                false,
                [
                    $this,
                    'onResponse'
                ]
            );
        }

        public function onResponse(AMQPMessage $rep)
        {
            if ($rep->get('correlation_id') === $this->corr_id) {
                $this->response = $rep->getBody();
            }
        }

        public function call(int $n)
        {
            $this->response = null;
            $this->corr_id = uniqid();

            $msg = new AMQPMessage(
                (string) $n,
                [
                    'correlation_id' => $this->corr_id,
                    'reply_to' => $this->callback_queue,
                ]
            );
            $this->channel->basic_publish($msg, '', 'rpc_queue');
            while (!$this->response) {
                $this->channel->wait();
            }

            return intval($this->response);
        }
    }

    $fibonacci_rpc = new FibonacciRpcClient();
    $response = $fibonacci_rpc->call(30);
    echo ' [.] Got ', $response, "\n";

