            hResponse.put("X-Response-ID", hIncoming.getFirst("X-Request-ID"));
            hResponse.put(keys, hIncoming.get(keys));
        }
        nc.publish(msg.getReplyTo(), hResponse, msg.getData());
    });
    dService.subscribe("service");

