    ack, err := batch.Commit(ctx, "orders.created", []byte(`{"order":"ORD-42","sku":"MUG-WHITE","qty":4}`))
    if err != nil {
    	log.Fatalf("commit batch: %v", err)
    }
    log.Printf("batch %q committed: %d line items stored", ack.BatchID, ack.BatchSize)

