    try {
      await js.publish("no-ttl.msg", "order ord_8w2k cancelled", { ttl: "60s" });
    } catch (err) {
      if (err instanceof JetStreamApiError) {
        console.log(`Rejected (err ${err.code}): ${err.message}`);
        console.log("Nothing was stored");
      } else {
        throw err;
