    # no subjects of its own; it follows the upstream stream.
    info = await js.add_stream(name="ORDERS-ARCHIVE", mirror=StreamSource(name="ORDERS"))

    print(f"Created mirror {info.config.name} of {info.config.mirror.name}")

Java

