    const jsm = await jetstreamManager(nc);
    const info = await jsm.streams.info("ORDERS-ARCHIVE");
    console.log(`Upstream:  ${info.mirror?.name}`);
    console.log(`Lag:       ${info.mirror?.lag}`);
    console.log(`Last seen: ${info.mirror?.active} ns ago`);

