    // that many. This drains everything stored without assuming a count.
    info, err := cons.Info(ctx)
    if err != nil {
    	panic(err)
    }
    pending := info.NumPending
    if pending == 0 {
    	fmt.Println("nothing to read")
    	return
    }

    msgs, err := cons.Fetch(int(pending))
    if err != nil {
    	panic(err)
