    // keeps the customer id, so `ingest.acme` becomes `orders.<0-2>.acme`.
    const info = await jsm.streams.add({
      name: "ORDERS-SHARDED",
      subjects: ["ingest.*"],
      subject_transform: {
        src: "ingest.*",
        dest: "orders.{{partition(3,1)}}.{{wildcard(1)}}",
      },
    });
    console.log(`Created stream: ${info.config.name}`);

